const config = $input.first().json;
const now = new Date();
const draftId = "ffs-video-" + now.toISOString().replace(/[-:.TZ]/g, "").slice(0, 14);
const topicSeeds = [
  "emergency fund before investing",
  "compound interest for beginners",
  "inflation explained with everyday examples",
  "budgeting without feeling restricted",
  "good debt versus bad debt",
  "lifestyle inflation and how to avoid it",
  "saving versus investing",
  "beginner money mistakes to avoid"
];
const seedTopic = topicSeeds[Math.floor(Math.random() * topicSeeds.length)];
const prompt =
  "You are the content brain for " + config.channelName +
  ". Create a complete YouTube Shorts production package for a finance channel." +
  " Seed topic: " + seedTopic +
  ". Owner: " + config.ownerEmail +
  ". Manager account for Google/API work: " + config.managerEmail +
  ". Mode: draft + approval only, do not publish automatically." +
  " Return strict JSON only with keys: topic, angle, hook, script, scene_plan," +
  " voice_notes, editing_instructions, thumbnail_prompt, thumbnail_text, title," +
  " description, hashtags, keywords, category, compliance_disclaimer, performance_notes." +
  " Rules: beginner friendly, no personal financial advice, no fake earnings claims," +
  " no guaranteed returns, no copyrighted brand assets, optimize title, thumbnail," +
  " hashtags and keywords for Shorts discovery.";

return [{
  json: {
    ...config,
    draftId,
    seedTopic,
    prompt,
    createdAt: now.toISOString(),
    status: "Generating Content Package"
  }
}];

const base = $node["Build Content Brief"].json;
const response = $input.first().json;

function safeParse(value) {
  if (!value) return {};
  if (typeof value === "object") return value;
  try {
    return JSON.parse(value);
  } catch {
    return { rawText: String(value) };
  }
}

const body = safeParse(response.body ?? response.data ?? response);
const pkg = body.package ?? body.draft ?? body.result ?? body.output ?? body;
const topic = pkg.topic || base.seedTopic;
const hook = pkg.hook || ("Most people miss this money lesson: " + topic + ".");
const script = pkg.script || pkg.rawText || (
  hook + "\n\nHere is the simple version of " + topic +
  ". Keep this educational, not personal financial advice."
);
const defaultScenes = [
  {
    scene: 1,
    duration_seconds: 4,
    narration: hook,
    on_screen_text: hook,
    visual_prompt: "Clean vertical finance visual about " + topic,
    editing_note: "Fast hook, bold captions"
  },
  {
    scene: 2,
    duration_seconds: 12,
    narration: script,
    on_screen_text: "Simple money lesson",
    visual_prompt: "Beginner friendly finance animation about " + topic,
    editing_note: "Cut every 2-3 seconds"
  },
  {
    scene: 3,
    duration_seconds: 8,
    narration: "Educational content only, not personal financial advice.",
    on_screen_text: "Educational only",
    visual_prompt: "Clean disclaimer end card",
    editing_note: "Clear small disclaimer"
  }
];
const scenePlan = Array.isArray(pkg.scene_plan) && pkg.scene_plan.length ? pkg.scene_plan : defaultScenes;
const hashtags = Array.isArray(pkg.hashtags) ? pkg.hashtags : ["#Finance", "#MoneyTips", "#PersonalFinance", "#Shorts"];
const keywords = Array.isArray(pkg.keywords) ? pkg.keywords : ["finance", "money tips", "personal finance", topic];
const title = pkg.title || (topic + " in 45 Seconds #Shorts");
const disclaimer = pkg.compliance_disclaimer || pkg.disclaimer || "Educational content only. Not personal financial advice.";
const description = pkg.description || (hook + "\n\n" + disclaimer + "\n\n" + hashtags.join(" "));
const thumbnailPrompt = pkg.thumbnail_prompt || (
  "High CTR YouTube Shorts thumbnail about " + topic +
  ", bold clean finance design, no copyrighted logos, readable text"
);
const thumbnailText = pkg.thumbnail_text || "Money Tip";

return [{
  json: {
    ...base,
    status: "Content Package Ready",
    topic,
    angle: pkg.angle || "",
    hook,
    script,
    scenePlan,
    voiceNotes: pkg.voice_notes || "Clear confident voice, beginner friendly, energetic but trustworthy.",
    editingInstructions: pkg.editing_instructions || "Vertical 9:16, captions on every line, fast pacing, clean finance visuals, disclaimer at end.",
    thumbnailPrompt,
    thumbnailText,
    title,
    description,
    hashtags: hashtags.join(" "),
    keywords: keywords.join(", "),
    category: pkg.category || "Education",
    disclaimer,
    performanceNotes: pkg.performance_notes || "",
    contentPackageJson: JSON.stringify(pkg)
  }
}];

const base = $node["Normalize Content Package"].json;
const response = $input.first().json;
const voiceUrl = response.audioUrl || response.voiceUrl || response.url || response.data?.audioUrl || response.body?.audioUrl || "";
const voiceAssetId = response.assetId || response.voiceAssetId || response.id || "";

return [{
  json: {
    ...base,
    status: voiceUrl ? "Voice Ready" : "Voice Pending API Setup",
    voiceUrl,
    voiceAssetId,
    voiceApiResponse: JSON.stringify(response)
  }
}];

const base = $node["Normalize Voice Result"].json;
const response = $input.first().json;
const sceneAssets = response.sceneAssets || response.assets || response.images || response.data?.sceneAssets || [];
const thumbnailUrl = response.thumbnailUrl || response.thumbnail_url || response.data?.thumbnailUrl || "";

return [{
  json: {
    ...base,
    status: thumbnailUrl || sceneAssets.length ? "Visual Assets Ready" : "Visual Assets Pending API Setup",
    sceneAssets,
    thumbnailUrl,
    visualApiResponse: JSON.stringify(response)
  }
}];

const base = $node["Normalize Visual Assets"].json;
const response = $input.first().json;
const videoUrl = response.videoUrl || response.video_url || response.url || response.data?.videoUrl || "";
const thumbnailUrl = response.thumbnailUrl || response.thumbnail_url || base.thumbnailUrl || "";
const renderJobId = response.jobId || response.renderJobId || response.id || "";

return [{
  json: {
    ...base,
    status: videoUrl ? "Video Rendered" : "Video Pending API Setup",
    videoUrl,
    thumbnailUrl,
    renderJobId,
    videoApiResponse: JSON.stringify(response)
  }
}];

const base = $node["Normalize Video Result"].json;
const response = $input.first().json;
const youtubeVideoId = response.uploadId || response.youtubeVideoId || response.videoId || response.id || response.data?.id || response.body?.id || "";
const youtubeDraftUrl =
  response.youtubeDraftUrl ||
  response.draftUrl ||
  response.url ||
  response.data?.youtubeDraftUrl ||
  (youtubeVideoId ? "https://studio.youtube.com/video/" + youtubeVideoId + "/edit" : "");
const youtubeUploadError = response.error?.message || response.error || response.message || "";
const approveUrl = base.approvalBaseUrl + "?draftId=" + encodeURIComponent(base.draftId) + "&action=approve";
const rejectUrl = base.approvalBaseUrl + "?draftId=" + encodeURIComponent(base.draftId) + "&action=reject";
const approvalEmailHtml =
  "<h2>Review YouTube Short Draft</h2>" +
  "<p><strong>Title:</strong> " + base.title + "</p>" +
  "<p><strong>Topic:</strong> " + base.topic + "</p>" +
  "<p><strong>Status:</strong> Ready for approval, not published.</p>" +
  "<p><strong>Video:</strong> <a href=\"" + base.videoUrl + "\">Open rendered video</a></p>" +
  "<p><strong>Thumbnail:</strong> <a href=\"" + base.thumbnailUrl + "\">Open thumbnail</a></p>" +
  (youtubeDraftUrl
    ? "<p><strong>YouTube private draft:</strong> <a href=\"" + youtubeDraftUrl + "\">Open in YouTube Studio</a></p>"
    : "<p><strong>YouTube private draft:</strong> Not created yet. Check the YouTube upload node credentials/output.</p>") +
  (youtubeUploadError ? "<p><strong>YouTube upload note:</strong> " + youtubeUploadError + "</p>" : "") +
  "<h3>Script</h3><pre style=\"white-space:pre-wrap;font-family:Arial,sans-serif\">" + base.script + "</pre>" +
  "<h3>Description</h3><pre style=\"white-space:pre-wrap;font-family:Arial,sans-serif\">" + base.description + "</pre>" +
  "<p><strong>Hashtags:</strong> " + base.hashtags + "</p>" +
  "<p><strong>Keywords:</strong> " + base.keywords + "</p>" +
  "<p><a href=\"" + approveUrl + "\">Approve</a> | <a href=\"" + rejectUrl + "\">Reject</a></p>" +
  "<p>This workflow does not auto-publish.</p>";

return [{
  json: {
    ...base,
    status: youtubeDraftUrl ? "Pending Approval - YouTube Private Draft Ready" : "Pending Approval - YouTube Upload Needs Attention",
    youtubeDraftUrl,
    youtubeVideoId,
    youtubeUploadError,
    approveUrl,
    rejectUrl,
    approvalEmailHtml,
    youtubeApiResponse: JSON.stringify(response)
  }
}];

const query = $input.first().json.query || {};
const draftId = query.draftId || "unknown-draft";
const action = String(query.action || "").toLowerCase();
const status = action === "approve" ? "Approved - Ready to Post" : action === "reject" ? "Rejected - Needs Revision" : "Needs Review";
const reviewedAt = new Date().toISOString();

return [{
  json: {
    draftId,
    action,
    status,
    reviewedAt,
    reviewedBy: "sajvindersingh8@gmail.com",
    message: "Draft " + draftId + " marked as " + status + "."
  }
}];
